func TestTextChaining(t *testing.T) {
	got := string(noscript.New().Class("foo").Text("content").ID("bar").RenderBytes())
	want := `<noscript class="foo" id="bar">content</noscript>`
	if got != want {
		t.Errorf("got %q, want %q", got, want)
	}
}

func TestDynamicKey(t *testing.T) {
	got := string(noscript.New().Dynamic("mykey").RenderBytes())
	want := `<noscript data-fluent-key="mykey"></noscript>`
	if got != want {
		t.Errorf("got %q, want %q", got, want)
	}
}

func TestMemoiseKey(t *testing.T) {
	el := noscript.New()
	if el.MemoiseKey() != nil {
		t.Error("new element should have no memoise version")
	}
	el.Memoise(7)
	if el.MemoiseKey() != 7 {
		t.Errorf("MemoiseKey() = %v, want 7", el.MemoiseKey())
	}
}

func TestNotDynamic(t *testing.T) {
	el := noscript.New()
	if el.IsDynamic() {
		t.Error("new element should not be dynamic")
	}
	if el.DynamicKey() != "" {
		t.Errorf("DynamicKey() should be empty, got %q", el.DynamicKey())
	}
}

func TestRenderMethodsMatch(t *testing.T) {
	el := noscript.New()
	el.SetAttribute("data-check", "render")
	want := string(el.RenderBytes())

	var buf bytes.Buffer
	el.Render(&buf)
	if buf.String() != want {
		t.Errorf("Render: got %q, want %q", buf.String(), want)
	}

	buf.Reset()
	n, err := el.WriteTo(&buf)
	if err != nil {
		t.Fatalf("WriteTo: %v", err)
	}
	if buf.String() != want {
		t.Errorf("WriteTo: got %q, want %q", buf.String(), want)
	}
	if n != int64(len(want)) {
		t.Errorf("WriteTo returned %d bytes, want %d", n, len(want))
	}

	buf.Reset()
	el.RenderBuilder(&buf)
	if buf.String() != want {
		t.Errorf("RenderBuilder: got %q, want %q", buf.String(), want)
	}

	buf.Reset()
	el.RenderOpen(&buf)
	el.RenderClose(&buf)
	if buf.String() != want {
		t.Errorf("RenderOpen+RenderClose: got %q, want %q", buf.String(), want)
	}
}

func TestSetAttributeEscapes(t *testing.T) {
	el := noscript.New()
	el.SetAttribute("data-sample", "\"><script>")
	got := string(el.RenderBytes())
	want := `<noscript data-sample="&#34;&gt;&lt;script&gt;"></noscript>`
	if got != want {
		t.Errorf("got %q, want %q", got, want)
	}
}

func TestSetAttributeRaw(t *testing.T) {
	el := noscript.New()
	// A pre-escaped entity must render verbatim; SetAttribute would double-escape it.
	el.SetAttributeRaw("data-sample", "a&amp;b")
	got := string(el.RenderBytes())
	want := `<noscript data-sample="a&amp;b"></noscript>`
	if got != want {
		t.Errorf("got %q, want %q", got, want)
	}
}
